$count=0;
function check($ok,$label){global $count;if(!$ok)throw new RuntimeException($label);$count++;}
function denied(callable $f,int $status){try{$f();throw new RuntimeException('Expected denial '.$status);}catch(Symfony\Component\HttpKernel\Exception\HttpExceptionInterface $e){check($e->getStatusCode()===$status,'Expected '.$status.' got '.$e->getStatusCode().' '.$e->getMessage());}}
function trackingRequest(array $b=[],?string $token=null):Request{return Request::create('/tracking','POST',[],[],[],['CONTENT_TYPE'=>'application/json',...($token?['HTTP_AUTHORIZATION'=>'Bearer '.$token]:[])],json_encode($b));}
function row(string $table,array $data=[]):string{
 $uuid=(string)Str::uuid();$base=['uuid'=>$uuid,'public_id'=>rtrim($table,'s').'_DEMO_'.str_replace('-','',$uuid),'name'=>'DEMO tracking QA','meta'=>json_encode(['mapa_demo'=>true]),'created_at'=>now(),'updated_at'=>now()];
 $columns=array_column(DB::select("SHOW COLUMNS FROM `$table`"),'Field');DB::table($table)->insert(array_intersect_key([...$base,...$data],array_flip($columns)));return $uuid;
}
